const canRunCommand = (
  bin: string,
  executeHostCommand: HostCommandExecutor = executeHostCommandSync,
): boolean => {
  try {
    executeHostCommand(bin, ['--version'], { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
};

const binaryDetect = (bin: string) => (): boolean => canRunCommand(bin);

const reportAllowlistWrite = (
  label: string,
  filePath: string,
  result: AllowlistWriteResult,
): boolean => {
  if (!result.ok) {
    console.log(
      `  Error: could not write the ${label} command allowlist (${filePath}): ${result.error}`,
    );
    console.log('  Run this in your own terminal instead:');
    console.log('    npx -y rivet-design@latest install');
    return false;
  }
  console.log(
    result.changed
      ? `✓ Command allowlist written to ${filePath}`
      : `✓ Command allowlist already present in ${filePath}`,
  );
  if (result.verified) {
    console.log(
      '✓ Verified: `rivet` invocations run without an approval prompt.',
    );
  } else {
    console.log(
      '  Warning: could not verify the allowlist entry — the host may still prompt per call.',
    );
  }
  return true;
};

const claudeSkillDir = (): string => path.dirname(claudeSkillPath());

export const resolveClaudeCodeCommand = (options?: {
  homeDir?: string;
  operatingSystemServices?: Pick<OperatingSystemServices, 'hostCommands'>;
}): string | undefined => {
  const homeDir = options?.homeDir ?? os.homedir();
  const operatingSystemServices =
    options?.operatingSystemServices ?? selectedOperatingSystemServices;
  const standaloneCommand = path.join(
    homeDir,
    '.local',
    'bin',
    operatingSystemServices.hostCommands.nativeExecutableName('claude'),
  );
  return ['claude', standaloneCommand].find((command) =>
    canRunCommand(command, (bin, args, commandOptions) =>
      operatingSystemServices.hostCommands.executeSync(
        { executable: bin, args },
        commandOptions,
      ),
    ),
  );
};

const isClaudeCodeCliAvailable = (): boolean =>
  resolveClaudeCodeCommand() !== undefined;

type ClaudeDesktopInstallationPaths = {
  applicationPath?: string;
  configPath: string;
};

export const detectClaudeDesktopInstallation = ({
  applicationPath,
  configPath,
}: ClaudeDesktopInstallationPaths): boolean =>
  fs.existsSync(path.dirname(configPath)) ||
  (applicationPath !== undefined && fs.existsSync(applicationPath));

const isClaudeDesktopAppPresent = (): boolean =>
  detectClaudeDesktopInstallation({
    applicationPath:
      process.env.RIVET_CLAUDE_DESKTOP_APP ??
      (process.platform === 'darwin' ? '/Applications/Claude.app' : undefined),
    configPath: claudeDesktopConfigPath(),
  });

const isClaudeCodeAvailable = (): boolean =>
  isClaudeCodeCliAvailable() || isClaudeDesktopAppPresent();

const hasClaudeHarnessInstallation = (): boolean => {
  if (
    hasClaudeSkill() ||
    claudeWorkerAgentPaths().some(hasClaudeWorkerAgent) ||
    verifyClaudeAllowlist()
  ) {
    return true;
  }
  const claudeCodeCommand = resolveClaudeCodeCommand();
  return (
    claudeCodeCommand !== undefined &&
    hasRivetRegistrationViaHostCli(claudeCodeCommand)
  );
};

const hasCursorHarnessInstallation = (): boolean =>
  hasCursorSkill() ||
  verifyCursorAllowlist() ||
  verifyCursorEditorAllowlist() ||
  hasCursorRivetRegistration();

const hasCodexHarnessInstallation = (): boolean =>
  hasCodexGuidance() ||
  hasCodexSkill() ||
  verifyCodexRules() ||
  hasRivetRegistrationViaHostCli('codex');

const reportMcpRegistration = (
  label: string,
  result: McpRegistrationResult,
): boolean => {
  if (!result.ok) {
    console.log(
      `  Error: could not register the Rivet MCP server with ${label}: ${result.error}`,
    );
    return false;
  }
  console.log(
    result.changed
      ? `✓ Configured the Rivet MCP server (\`rivet mcp serve\`) for ${label}`
      : `✓ Rivet MCP server already configured for ${label}`,
  );
  return true;
};

const installClaudeDesktopMcp = (): InstallOutcome => {
  const result = registerClaudeDesktopMcp();
  const isConfigured = reportMcpRegistration(
    'the Claude desktop app (claude_desktop_config.json)',
    result,
  );
  if (!isConfigured) return { ok: false, changed: result.changed };
  const verification = verifyMcpServeInvocation();
  if (!verification.ok) {
    console.log(
      `  Error: the configured Rivet MCP server did not start: ${verification.error}`,
    );
    return { ok: false, changed: result.changed };
  }
  console.log('✓ Verified the Rivet MCP server starts and lists its tools');
  console.log(
    '  Claude Desktop has no working directory: tools take a `project` parameter — tell the agent which project root to target.',
  );
  return { ok: true, changed: result.changed };
};

const claudeHarness: Harness = {
  id: 'claude',
  label: 'Claude Code',
  sendButtonLabel: 'Send to Claude Code',
  installUrl: 'https://claude.ai/download',
  supportsMcp: true,
  detect: isClaudeCodeAvailable,
  isInstalled: hasClaudeHarnessInstallation,
  notInstalledMessage: () =>
    'Claude Code is not installed as a terminal command or through the Claude desktop app.\nInstall it: https://claude.ai/download',
  install: (options?: HarnessInstallOptions): InstallOutcome => {
    const claudeCodeCommand = resolveClaudeCodeCommand();
    const skill = writeSkillFileIfNeeded();
    if (skill.success) {
      console.log('✓ Rivet CLI skill installed for Claude Code');
    } else {
      console.log(
        `  Warning: could not write skill file to ${claudeSkillDir()}: ${skill.error}`,
      );
    }
    const workerAgent = writeWorkerAgentIfNeeded();
    if (workerAgent.success) {
      console.log(
        '✓ Rivet worker agents installed for Claude Code (variant workers run fidelity-matched model/effort)',
      );
    } else {
      console.log(
        `  Warning: could not write worker agents under ${path.dirname(claudeWorkerAgentPath())}: ${workerAgent.error}`,
      );
    }
    const allowlistOk = reportAllowlistWrite(
      'Claude Code',
      claudeSettingsPath(),
      writeClaudeAllowlist(),
    );
    if (cleanupClaudeLegacyMcp({ bin: claudeCodeCommand }).changed) {
      console.log(
        '✓ Removed the MCP registration a previous Rivet version wrote',
      );
    }
    let mcpOk = true;
    if (options?.mcp && claudeCodeCommand !== undefined) {
      mcpOk = reportMcpRegistration(
        'Claude Code',
        registerClaudeCodeMcp(executeHostCommandSync, claudeCodeCommand),
      );
    } else if (options?.mcp) {
      console.log(
        '  Skipped Claude Code MCP registration: the `claude` terminal command is not available. CLI guidance and permissions are installed. Run `rivet install claude` after installing the command to add MCP.',
      );
    }
    return {
      ok: skill.success && workerAgent.success && allowlistOk && mcpOk,
      changed: true,
    };
  },
  uninstall: (): boolean => {
    let changed = false;
    if (hasClaudeSkill()) {
      fs.rmSync(claudeSkillPath(), { force: true });
      console.log('✓ Rivet skill file removed for Claude Code');
      changed = true;
    }
    let isWorkerAgentRemoved = false;
    for (const workerAgentPath of claudeWorkerAgentPaths()) {
      if (hasClaudeWorkerAgent(workerAgentPath)) {
        fs.rmSync(workerAgentPath, { force: true });
        changed = true;
        isWorkerAgentRemoved = true;
      }
    }
    if (isWorkerAgentRemoved) {
      console.log('✓ Rivet worker agents removed for Claude Code');
    }
    const allowlist = removeClaudeAllowlist();
    if (allowlist.ok && allowlist.changed) {
      console.log(
        `✓ Command allowlist entries removed from ${claudeSettingsPath()}`,
      );
      changed = true;
    }
    const claudeCodeCommand = resolveClaudeCodeCommand();
    if (
      unregisterClaudeCodeMcp(
        executeHostCommandSync,
        claudeCodeCommand ?? 'claude',
      ).changed
    ) {
      console.log('✓ Rivet MCP registration removed from Claude Code');
      changed = true;
    }
    return changed;
  },
  update: (options?: HarnessUpdateOptions): boolean => {
    if (!hasClaudeHarnessInstallation()) {
      return false;
    }
    const claudeCodeCommand = resolveClaudeCodeCommand();
    const hadServeRegistration =
      claudeCodeCommand !== undefined &&
      hasServeRegistrationViaHostCli(claudeCodeCommand);
    const skill = writeSkillFileIfNeeded();
    const workerAgent = writeWorkerAgentIfNeeded();
    const allowlist = writeClaudeAllowlist();
    cleanupClaudeLegacyMcp({ bin: claudeCodeCommand });
    let isMcpRefreshSuccessful = true;
    if (hadServeRegistration && claudeCodeCommand !== undefined) {
      isMcpRefreshSuccessful = registerClaudeCodeMcp(
        executeHostCommandSync,
        claudeCodeCommand,
      ).ok;
    }
    const updated =
      skill.success &&
      workerAgent.success &&
      allowlist.ok &&
      isMcpRefreshSuccessful;
    if (updated && !options?.isQuiet) {
      console.log('✓ Refreshed Rivet CLI guidance for Claude Code');
    }
    return updated;
  },
  nextSteps: `
Next steps:
  1. Start a new Claude Code session in your terminal or the desktop app
  2. Type /rivet or say "Open Rivet"
`,
  summaryHint: 'start a new session, then /rivet',
  restartHint: 'Restart Claude Code to apply changes.',
};

const cursorHarness: Harness = {
  id: 'cursor',
  label: 'Cursor',
  sendButtonLabel: 'Send to Cursor',
  installUrl: 'https://cursor.com',
  supportsMcp: true,
  detect: (): boolean =>
    fs.existsSync(path.join(os.homedir(), '.cursor')) ||
    fs.existsSync(path.dirname(cursorPermissionsPath())),
  isInstalled: hasCursorHarnessInstallation,
  notInstalledMessage: () =>
    'Cursor does not appear to be installed (~/.cursor not found).\nInstall it: https://cursor.com',
  install: (options?: HarnessInstallOptions): InstallOutcome => {
    const skill = writeCursorSkill();
    if (skill.ok) {
      console.log(`✓ Rivet skill installed at ${cursorSkillPath()}`);
    } else {
      console.log(`  Error: could not install the Rivet skill: ${skill.error}`);
    }
    const allowlistOk = reportAllowlistWrite(
      'Cursor',
      cursorPermissionsPath(),
      writeCursorAllowlist(),
    );
    if (cleanupCursorLegacyMcp().changed) {
      console.log(
        '✓ Removed the MCP entries a previous Rivet version wrote to ~/.cursor/mcp.json',
      );
    }
    let mcpOk = true;
    if (options?.mcp) {
      mcpOk = reportMcpRegistration(
        'Cursor (~/.cursor/mcp.json)',
        registerCursorMcp(),
      );
    }
    return { ok: skill.ok && allowlistOk && mcpOk, changed: true };
  },
  uninstall: (): boolean => {
    let changed = false;
    const skill = removeCursorSkill();
    if (skill.ok && skill.changed) {
      console.log('✓ Rivet skill removed for Cursor');
      changed = true;
    } else if (!skill.ok) {
      console.log(`  Error: could not remove the Rivet skill: ${skill.error}`);
    }
    const editorAllowlist = removeCursorEditorAllowlist();
    if (editorAllowlist.ok && editorAllowlist.changed) {
      console.log('✓ Rivet editor command entries removed for Cursor');
      changed = true;
    } else if (!editorAllowlist.ok) {
      console.log(
        `  Error: could not remove Rivet's editor command entries: ${editorAllowlist.error}`,
      );
    }
    const allowlist = removeCursorAllowlist();
    if (allowlist.ok && allowlist.changed) {
      console.log(
        `✓ Command allowlist entries removed from ${cursorPermissionsPath()}`,
      );
      changed = true;
    }
    if (cleanupCursorLegacyMcp().changed) {
      console.log('✓ Removed legacy Rivet MCP entries from ~/.cursor/mcp.json');
      changed = true;
    }
    if (unregisterCursorMcp().changed) {
      console.log('✓ Rivet MCP registration removed from ~/.cursor/mcp.json');
      changed = true;
    }
    return changed;
  },
  update: (options?: HarnessUpdateOptions): boolean => {
    if (!hasCursorHarnessInstallation()) return false;
    const hadServeRegistration = hasCursorServeRegistration();
    const skill = writeCursorSkill();
    if (!skill.ok && !options?.isQuiet) {
      console.log(`  Error: could not refresh the Rivet skill: ${skill.error}`);
    }
    const allowlist = writeCursorAllowlist();
    cleanupCursorLegacyMcp();
    let isMcpRefreshSuccessful = true;
    if (hadServeRegistration) {
      isMcpRefreshSuccessful = registerCursorMcp().ok;
    }
    if (skill.ok && allowlist.ok && !options?.isQuiet) {
      console.log('✓ Refreshed Rivet CLI guidance and permissions for Cursor');
    }
    return skill.ok && allowlist.ok && isMcpRefreshSuccessful;
  },
  nextSteps: `
Next steps:
  1. Start a new Cursor agent session in your terminal or desktop app
  2. Say "Open Rivet" — the agent drives Rivet with \`rivet\` commands
`,
  summaryHint: 'open a project, then say "Open Rivet"',
  restartHint: 'Restart Cursor to apply changes.',
};

