const claudeDesktopHarness: Harness = {
  id: 'claude-desktop',
  label: 'the Claude desktop app',
  sendButtonLabel: 'Send to Claude',
  installUrl: 'https://claude.ai/download',
  isRetired: true,
  supportsMcp: true,
  detect: isClaudeDesktopAppPresent,
  isInstalled: hasClaudeDesktopRivetRegistration,
  notInstalledMessage: () =>
    `Claude desktop does not appear to be installed (${path.dirname(
      claudeDesktopConfigPath(),
    )} not found).\nInstall it: https://claude.ai/download`,
  install: (options?: HarnessInstallOptions): InstallOutcome => {
    if (options?.mcp) {
      return installClaudeDesktopMcp();
    }
    console.log(CLAUDE_DESKTOP_OUT_OF_SCOPE_MESSAGE);
    const cleanup = cleanupClaudeDesktopLegacyMcp();
    if (cleanup.changed) {
      console.log(
        '✓ Removed the MCP registration a previous Rivet version wrote to claude_desktop_config.json',
      );
    }
    return { ok: true, changed: cleanup.changed };
  },
  uninstall: (): boolean => {
    const legacy = cleanupClaudeDesktopLegacyMcp();
    const serve = unregisterClaudeDesktopMcp();
    const changed = legacy.changed || serve.changed;
    if (changed) {
      console.log(
        `✓ Rivet MCP registration removed from ${claudeDesktopConfigPath()}`,
      );
    } else {
      console.log(
        '  Rivet was not registered with the Claude desktop app (nothing to remove).',
      );
    }
    return changed;
  },
  update: (_options?: HarnessUpdateOptions): boolean => {
    if (!hasClaudeDesktopRivetRegistration()) return false;
    const hadServeRegistration = hasClaudeDesktopServeRegistration();
    const legacy = cleanupClaudeDesktopLegacyMcp().changed;
    if (hadServeRegistration) {
      return registerClaudeDesktopMcp().ok;
    }
    return legacy;
  },
  nextSteps: `
Next steps:
  1. Fully restart the Claude desktop app (the MCP server loads on launch)
  2. In Settings > Developer, confirm the rivet server is running (managed
     organizations may need an admin to allow local developer MCP)
  3. Ask "Use rivet_get_exploration for /absolute/path/to/project"
`,
  summaryHint: 'restart the app; agent uses the rivet MCP tools',
  restartHint: 'Fully restart the Claude desktop app to apply changes.',
};

export const HARNESSES: Harness[] = [
  claudeHarness,
  claudeDesktopHarness,
  cursorHarness,
  codexHarness,
];

const HARNESS_ID_ALIASES: Record<string, string> = {
  'claude-code': 'claude',
};

export const findHarness = (id: string): Harness | undefined =>
  HARNESSES.find((h) => h.id === (HARNESS_ID_ALIASES[id] ?? id));

export const detectedHarnesses = (options?: HarnessInstallOptions): Harness[] =>
  HARNESSES.filter(
    (h) =>
      (!h.isRetired || (options?.mcp === true && h.supportsMcp === true)) &&
      h.detect(),
  );

export const sendButtonLabelFor = (id?: string): string =>
  (id && findHarness(id)?.sendButtonLabel) ?? 'Send to Claude Code';

const CLI_INSTALL_WELCOME = `
Welcome to Rivet!

Rivet is a design agent for your coding agent. Your agent drives it by
running \`rivet\` CLI commands — install writes the selected agent's usage guidance
and its command allowlist so those commands run without approval prompts,
and registers the resident MCP server (\`rivet mcp serve\`) when its host
command is available. Pass --no-mcp to skip the MCP registration.
`;

const supportedListBlock = (): string =>
  HARNESSES.map((h) => `  rivet install ${h.id.padEnd(16)}${h.label}`).join(
    '\n',
  );

const installNamedHarness = (
  target: string,
  options?: HarnessInstallOptions,
): { exitCode: number } => {
  const harness = findHarness(target);
  if (!harness) {
    console.log(`\nUnknown agent "${target}". Supported:\n`);
    console.log(supportedListBlock());
    console.log('');
    return { exitCode: 1 };
  }
  console.log(`\nSetting up Rivet for ${harness.label}...\n`);
  const result = harness.install(options);
  if (result.ok && result.changed) console.log(harness.nextSteps);
  return { exitCode: result.ok ? 0 : 1 };
};

type InstallProposal = {
  agentId: CallerAgentKind;
  label: string;
  evidence: string[];
};

type InstallConfirmation = {
  status: 'confirmation_required';
  proposal: InstallProposal | null;
  availableAgentIds: string[];
  question: string;
};

export type InstallTargetSelection =
  | { status: 'confirmed'; targetIds: string[] }
  | InstallConfirmation
  | { status: 'invalid'; error: string };

const OTHER_AGENT_MESSAGE =
  "Automatic integration is unavailable for other agents: Rivet does not install their guidance, permissions, MCP registration, or native worker integration. A shell-capable agent can invoke the Rivet CLI, but it should not install another agent's configuration as a substitute.";

const codingAgentLabel = (id: CallerAgentKind): string => {
  const harness = findHarness(id);
  if (!harness) {
    throw new Error(`No coding integration is registered for ${id}.`);
  }
  return harness.label;
};

export const reportInstallConfirmation = (
  selection: InstallConfirmation,
  installArgs: string[],
): { exitCode: number } => ({
  exitCode: emitResult(
    processCliIO,
    okResult('install', {
      ...selection,
      choices: [
        ...CALLER_AGENT_ALLOWLIST.filter((id) => findHarness(id)).map((id) => ({
          id,
          label: codingAgentLabel(id),
          invocation: {
            command: 'npx',
            args: ['-y', 'rivet-design@latest', 'install', id, ...installArgs],
          },
        })),
        { id: 'other', label: 'Other', message: OTHER_AGENT_MESSAGE },
      ],
      nextAction: {
        action: 'ask_user',
        requiresUserResponse: true,
        instruction:
          "Ask the user the question in this conversation and present the choices. Wait for the user's actual response before running any installation command. After confirmation, run only the chosen explicit-target invocation, passing its args as separate arguments. If the user chooses Other, explain its support limits and do not substitute another agent.",
      },
    }),
  ),
});

export const resolveInstallTargets = (
  target?: string | string[],
  options?: {
    callerAgent?: CallerAgentKind;
    callerEvidence?: string;
    env?: NodeJS.ProcessEnv;
  },
): InstallTargetSelection => {
  const requested = typeof target === 'string' ? [target] : (target ?? []);
  if (requested.includes('all')) {
    if (requested.length > 1) {
      return {
        status: 'invalid',
        error: 'The all target cannot be combined with named agents.',
      };
    }
    const targetIds = detectedHarnesses().map(({ id }) => id);
    if (targetIds.length === 0) {
      return {
        status: 'invalid',
        error:
          'No coding agents detected. Run `rivet install <agent>` with claude, codex, or cursor.',
      };
    }
    return { status: 'confirmed', targetIds };
  }
  if (requested.length > 0) {
    const unknownTarget = requested.find((id) => !findHarness(id));
    if (unknownTarget) {
      return {
        status: 'invalid',
        error: `Unknown agent "${unknownTarget}". ${OTHER_AGENT_MESSAGE}\nSupported coding agents: claude, codex, cursor.`,
      };
    }
    return { status: 'confirmed', targetIds: [...new Set(requested)] };
  }
  const env = options?.env ?? process.env;
  const declaredAgent = env[HANDOFF_ENV_VARS.agent]?.trim().toLowerCase();
  let callerAgent = options?.callerAgent;
  if (!callerAgent && declaredAgent) {
    callerAgent = (CALLER_AGENT_ALLOWLIST as readonly string[]).includes(
      declaredAgent,
    )
      ? (declaredAgent as CallerAgentKind)
      : 'unknown';
  }
  const callers = callerAgentEvidenceFromEnv(env);
  let proposal: InstallProposal | null = null;
  let question =
    'Rivet could not identify your agent. Which agent should Rivet install for?';
  if (callerAgent && !findHarness(callerAgent)) {
    question =
      'The caller agent is not supported. Choose your agent, or select Other for support details.';
  } else if (callerAgent) {
    proposal = {
      agentId: callerAgent,
      label: codingAgentLabel(callerAgent),
      evidence: [options?.callerEvidence ?? HANDOFF_ENV_VARS.agent],
    };
  } else if (callers.length === 1) {
    proposal = {
      agentId: callers[0].agent,
      label: codingAgentLabel(callers[0].agent),
      evidence: callers[0].evidence,
    };
  } else if (callers.length > 1) {
    question = `Conflicting caller identities detected (${callers.map(({ agent }) => agent).join(', ')}). Which agent should Rivet install for?`;
  }
  if (proposal) {
    question = `Rivet identified ${proposal.label} from this session. Install for ${proposal.label}, or choose another agent?`;
  }
  return {
    status: 'confirmation_required',
    proposal,
    availableAgentIds: detectedHarnesses()
      .filter(({ id }) =>
        (CALLER_AGENT_ALLOWLIST as readonly string[]).includes(id),
      )
      .map(({ id }) => id),
    question,
  };
};

export const installHarnesses = (
  target?: string | string[],
  options?: HarnessInstallOptions,
): { exitCode: number } => {
  const selection = resolveInstallTargets(target);
  if (selection.status === 'invalid') {
    console.log(`\n${selection.error}\n`);
    return { exitCode: 1 };
  }
  if (selection.status === 'confirmation_required') {
    const installArgs = options?.mcp === true ? [] : ['--no-mcp'];
    return reportInstallConfirmation(selection, installArgs);
  }
  console.log(CLI_INSTALL_WELCOME);
  let exitCode = 0;
  for (const id of selection.targetIds) {
    if (installNamedHarness(id, options).exitCode !== 0) exitCode = 1;
  }
  return { exitCode };
};

export const uninstallHarnesses = (
  target?: string | string[],
): { exitCode: number } => {
  const targets = Array.isArray(target) ? target : target ? [target] : [];
  if (targets.length === 0) {
    console.log('\nUsage: rivet uninstall <editor...|all>\n');
    console.log(
      HARNESSES.map(
        (h) => `  rivet uninstall ${h.id.padEnd(16)}Remove from ${h.label}`,
      ).join('\n'),
    );
    console.log(`  rivet uninstall ${'all'.padEnd(16)}Remove from all editors`);
    console.log('');
    return { exitCode: 0 };
  }

  if (targets.includes('all')) {
    if (targets.length > 1) {
      console.log('\nThe all target cannot be combined with named agents.\n');
      return { exitCode: 1 };
    }
    console.log('\nUninstalling Rivet from all editors...\n');
    const changed = HARNESSES.map((h) => h.uninstall()).some(Boolean);
    if (changed)
      console.log('\nRestart your editor sessions to apply changes.\n');
    return { exitCode: 0 };
  }

  let exitCode = 0;
  for (const targetId of [...new Set(targets)]) {
    const harness = findHarness(targetId);
    if (!harness) {
      console.log(
        `\nUnknown agent "${targetId}". Supported: ${HARNESSES.map((h) => h.id).join(', ')}, all\n`,
      );
      exitCode = 1;
      continue;
    }

    console.log(`\nUninstalling Rivet from ${harness.label}...\n`);
    if (harness.uninstall()) {
      console.log(`\n${harness.restartHint}\n`);
    }
  }
  return { exitCode };
};

export const updateHarnesses = (
  options?: HarnessUpdateOptions,
): HarnessUpdateResult => {
  if (!options?.isQuiet) {
    console.log('\nUpdating Rivet...\n');
  }
  const installedHarnesses = HARNESSES.filter((harness) =>
    harness.isInstalled(),
  );
  const refreshedCount = installedHarnesses.filter((harness) =>
    harness.update(options),
  ).length;
  if (installedHarnesses.length === 0) {
    if (!options?.isQuiet) {
      console.log(
        "No editors found to update. Run 'rivet install' to set Rivet up first.",
      );
    }
    return {
      detectedInstalledCount: 0,
      isSuccessful: true,
      refreshedCount: 0,
    };
  }
  const isSuccessful = refreshedCount === installedHarnesses.length;
  if (!isSuccessful) {
    if (!options?.isQuiet) {
      console.log('\nSome Rivet integrations could not be refreshed.\n');
    }
    return {
      detectedInstalledCount: installedHarnesses.length,
      isSuccessful,
      refreshedCount,
    };
  }
  if (!options?.isQuiet) {
    console.log(
      '\nRestart your editor session to use the refreshed Rivet integrations.\n',
    );
  }
  return {
    detectedInstalledCount: installedHarnesses.length,
    isSuccessful,
    refreshedCount,
  };
};

